const s2t=Object.fromEntries(CHAR_PAIRS.split(/\s+/).filter(x=>x.includes(':')).map(x=>x.split(':')));
function tr(v){if(typeof v!=='string')return v;if(settings.language!=='zh-Hant')return v;return TC[v]||Array.from(v,ch=>s2t[ch]||ch).join('')}
const E = (v='')=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const uid=()=>crypto?.randomUUID?.()||('m'+Date.now().toString(36)+Math.random().toString(36).slice(2));
const now=()=>new Date().toISOString();
const day=(v)=>v?new Date(v).toLocaleDateString(settings.language==='zh-Hant'?'zh-TW':'zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}):'—';
const short=(str,n=85)=>String(str||'').length>n?String(str).slice(0,n)+'…':String(str||'');
const stripHtml=(html)=>{const el=document.createElement('div');el.innerHTML=sanitizeRich(html||'');return el.textContent||''};
function sanitizeRich(input){const d=new DOMParser().parseFromString(String(input||''),'text/html');const allow=new Set(['P','BR','B','STRONG','I','EM','U','UL','OL','LI','H2','H3','BLOCKQUOTE','A','DIV']);const forbidden=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','FORM','VIDEO','AUDIO']);function walk(n){if(n.nodeType===3)return E(n.textContent);if(n.nodeType!==1||forbidden.has(n.tagName))return '';let inner=Array.from(n.childNodes).map(walk).join('');if(!allow.has(n.tagName))return inner;const tag=n.tagName.toLowerCase();let attrs='';if(tag==='a'){const href=n.getAttribute('href')||'';if(/^https?:\/\//i.test(href))attrs=` href="${E(href)}" target="_blank" rel="noopener noreferrer"`;}return `<${tag}${attrs}>${inner}</${tag}>`;}return Array.from(d.body.childNodes).map(walk).join('')}
const PATHS={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',image:'<rect width="18" height="18" x="3" y="3" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-5-5L5 21"/>',feather:'<path d="M20.24 12.24a6 6 0 0 0-8.49-8.49L3 12.5V21h8.5z"/><line x1="16" x2="2" y1="8" y2="22"/><line x1="17.5" x2="9" y1="15" y2="15"/>',settings:'<path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7z"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-1.76 1.76-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V20h-2.5v-.09a1.65 1.65 0 0 0-1-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06-1.76-1.76.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H6v-2.5h.09a1.65 1.65 0 0 0 1.51-1 1.65 1.65 0 0 0-.33-1.82l-.06-.06L8.97 7.1l.06.06a1.65 1.65 0 0 0 1.82.33 1.65 1.65 0 0 0 1-1.51V5h2.5v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06 1.76 1.76-.06.06a1.65 1.65 0 0 0-.33 1.82 1.65 1.65 0 0 0 1.51 1H20v2.5h-.09A1.65 1.65 0 0 0 19.4 15z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',chevron:'<path d="m9 18 6-6-6-6"/>',arrow:'<path d="m19 12-7 7-7-7" transform="rotate(90 12 12)"/>',back:'<path d="m15 18-6-6 6-6"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4z"/>',trash:'<path d="M3 6h18M8 6V4h8v2M5 6l1 15h12l1-15"/><path d="M10 11v6M14 11v6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5"/><path d="M4 17v4h16v-4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5"/><path d="M4 17v4h16v-4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',table:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M3 15h18M9 3v18"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',heart:'<path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m4 12 5 5L20 6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>',expand:'<path d="M8 3H5a2 2 0 0 0-2 2v3M16 3h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3M21 16v3a2 2 0 0 1-2 2h-3"/>',sparkle:'<path d="m12 3 1.9 5.7L20 11l-6.1 2.3L12 19l-1.9-5.7L4 11l6.1-2.3z"/><path d="m19 18 .5 1.5L21 20l-1.5.5L19 22l-.5-1.5L17 20l1.5-.5z"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2z"/><path d="M17 21v-8H7v8M7 3v5h8"/>'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[name]||PATHS.sparkle}</svg>`}
let db;let settings={...DEFAULT_SETTINGS};const records={ocs:[],paro:[],commissions:[],ideas:[]};
const state={section:'home',detailId:null,query:'',sort:'recent',display:'grid',editor:null,editorType:null,editorId:null,busy:false,quoteIndex:0,quoteLang:'zh',quotePaused:false};
let quoteInterval=null,quoteSwapTimeout=null;
let imageCache=new Map(),imagePending=new Map(),toastTimer=0,renderSequence=0;
function dbReq(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function openDatabase(){return new Promise((resolve,reject)=>{const req=indexedDB.open('maki-workbench',1);req.onupgradeneeded=()=>{let d=req.result;if(!d.objectStoreNames.contains('entries'))d.createObjectStore('entries',{keyPath:'key'});if(!d.objectStoreNames.contains('media'))d.createObjectStore('media',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function getItem(store,key){return dbReq(db.transaction(store,'readonly').objectStore(store).get(key))}
function getAll(store){return dbReq(db.transaction(store,'readonly').objectStore(store).getAll())}
function putItem(store,entry){return dbReq(db.transaction(store,'readwrite').objectStore(store).put(entry))}
function removeItem(store,key){return dbReq(db.transaction(store,'readwrite').objectStore(store).delete(key))}
async function refreshRecords(){const all=await getAll('entries');for(const type of TYPES) records[type]=all.filter(x=>x.type===type).map(x=>x.data);const prefs=all.find(x=>x.key==='settings');settings={...DEFAULT_SETTINGS,...(prefs?.value||{})};settings.higekiriQuotes=Array.isArray(settings.higekiriQuotes)?settings.higekiriQuotes.map(p=>({zh:String(p?.zh||''),ja:String(p?.ja||'')})):structuredClone(DEFAULT_HIGEKIRI_QUOTES);applySettings()}
async function saveSettings(){await putItem('entries',{key:'settings',type:'settings',value:settings});applySettings()}
function applySettings(){const root=document.documentElement;root.dataset.theme=settings.theme;root.dataset.font=settings.font;root.style.setProperty('--accent',settings.accent);root.style.setProperty('--accent-soft',mixHex(settings.accent,root.dataset.theme==='dark'?'#22252a':'#ffffff',.87));root.style.setProperty('--accent-dark',mixHex(settings.accent,'#261c1e',.24));root.lang=settings.language;document.title=settings.title;document.getElementById('sideBrand').textContent=settings.title;document.getElementById('mobileBrand').textContent=settings.title;document.getElementById('footerBrand').textContent=settings.title;}
function mixHex(c1,c2,amount){const cv=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));const a=cv(c1),b=cv(c2);return '#'+a.map((v,i)=>Math.round(v*(1-amount)+b[i]*amount).toString(16).padStart(2,'0')).join('')}
function mediaURL(id,kind='thumb'){if(!id)return Promise.resolve(null);const key=`${id}:${kind}`;if(imageCache.has(key))return Promise.resolve(imageCache.get(key));if(imagePending.has(key))return imagePending.get(key);const p=getItem('media',id).then(entry=>{if(!entry)return null;const url=URL.createObjectURL((kind==='thumb'&&entry.thumb)||entry.blob);imageCache.set(key,url);imagePending.delete(key);return url}).catch(()=>{imagePending.delete(key);return null});imagePending.set(key,p);return p}
async function hydrateImages(scope=document){const nodes=Array.from(scope.querySelectorAll('img[data-media]'));await Promise.all(nodes.map(async el=>{const url=await mediaURL(el.dataset.media,el.dataset.full==='1'?'full':'thumb');if(url&&el.isConnected){el.src=url;el.classList.remove('loading-image')}}))}
function invalidateImage(id){for(let key of [...imageCache.keys()]){if(key.startsWith(id+':')){URL.revokeObjectURL(imageCache.get(key));imageCache.delete(key)}}}
function img(mediaId,alt='',cls='',full=false){return mediaId?`<img class="${cls} loading-image" data-media="${E(mediaId)}" ${full?'data-full="1"':''} loading="lazy" alt="${E(alt)}"/>`:''}
function toast(msg,err=false){const node=document.getElementById('toastRoot');node.innerHTML=`<div class="toast ${err?'error':''}">${E(msg)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.innerHTML='',3300)}
function button(label,action,extra='',variant=''){return `<button class="btn ${variant}" data-action="${action}" ${extra}>${label}</button>`}
const plur=(num,s='条')=>`${num} ${s}`;
function setNav(section){state.section=section;state.detailId=null;state.query='';window.scrollTo({top:0,behavior:'instant'});render()}
function renderNav(){const nav=v=>`<button class="nav-item ${state.section===v.key?'active':''}" data-nav="${v.key}">${icon(v.icon,18)}<span>${E(tr(v.name))}</span></button>`;document.getElementById('sideNav').innerHTML=NAV.map(nav).join('');document.getElementById('mobileNav').innerHTML=NAV.filter(v=>v.key!=='settings').map(v=>`<button class="bottom-item ${state.section===v.key?'active':''}" data-nav="${v.key}">${icon(v.icon,21)}<span>${E(tr(v.name))}</span></button>`).join('');let page=NAV.find(x=>x.key===state.section)||NAV[0];document.getElementById('breadcrumbs').innerHTML=`${E(tr('书阁'))} <span class="crumb-divider">/</span> ${E(tr(page.name))}`;const top=document.getElementById('topAvatar');top.innerHTML=settings.avatarId?img(settings.avatarId,'个人头像'):'<span>✿</span>';document.getElementById('topSearchButton').innerHTML=icon('search',18);document.querySelector('[data-i18n="localSave"]').textContent=tr('仅存于此设备')}
function render(){stopQuoteRotation();renderNav();let html='';if(state.detailId){html=renderDetail(state.section,state.detailId)}else if(state.section==='home')html=renderHome();else if(state.section==='settings')html=renderSettings();else html=renderCollection(state.section);document.getElementById('main').innerHTML=html;if(state.section==='home'&&!state.detailId)startQuoteRotation();const seq=++renderSequence;hydrateImages(document.getElementById('main')).catch(console.error);hydrateImages(document.querySelector('.topbar')).catch(console.error)}
function empty(title,desc,action,label,small=false){return `<div class="empty-state" ${small?'style="min-height:220px;padding:26px 18px"':''}><div class="empty-medallion">✿</div><h3>${E(tr(title))}</h3><p>${E(tr(desc))}</p>${action?button(`${icon('plus',15)}${E(tr(label))}`,action,'','btn-primary'):''}</div>`}
function rowHeader(eyebrow,title,subtitle,action,label){return `<div class="page-header"><div><div class="eyebrow">${E(eyebrow)}</div><h1 class="page-title">${E(tr(title))}</h1><p class="section-subtitle">${E(tr(subtitle))}</p></div>${action?`<div class="header-actions">${button(`${icon('plus',16)}${E(tr(label))}`,action,'','btn-primary')}</div>`:''}</div>`}
function mediaCount(){return records.ocs.reduce((a,r)=>a+(r.gallery?.length||0)+(r.coverId?1:0),0)+records.commissions.reduce((a,r)=>a+(r.stages?.length||0),0)}
function recentOf(type,n=3){return [...records[type]].sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')).slice(0,n)}
function homeRecentRow(r,type){const cover=type==='ocs'?r.coverId:type==='commissions'?(r.stages?.at(-1)?.mediaId):null;const name=r.name||r.title||'未命名';return `<div class="mini-row"><div class="mini-icon">${cover?img(cover,name):'✿'}</div><div class="mini-row-body"><div class="mini-row-title">${E(name)}</div><div class="mini-row-meta">${E(type==='ocs'?(r.world||tr('角色档案')):type==='commissions'?'约稿作品':type==='paro'?'PARO':'灵感')} · ${E(day(r.updatedAt))}</div></div><button class="icon-button mini-row-arrow" data-action="detail" data-type="${type}" data-id="${E(r.id)}" aria-label="查看">${icon('chevron')}</button></div>`}
function getHigekiriQuotes(){const custom=settings.higekiriQuotes;const all=Array.isArray(custom)&&custom.length?custom:DEFAULT_HIGEKIRI_QUOTES;return all.filter(x=>x&&typeof x==='object').map(x=>({zh:String(x.zh||'').trim(),ja:String(x.ja||'').trim()})).filter(x=>x.zh||x.ja).slice(0,40)}
function quoteLine(pair,lang){return (pair[lang]||pair[lang==='zh'?'ja':'zh']||'').trim()}
function quoteReadout(quotes){const i=state.quoteIndex%quotes.length,pair=quotes[i];return {text:quoteLine(pair,state.quoteLang),index:i,lang:state.quoteLang}}
function quoteHero(){const quotes=getHigekiriQuotes();if(!quotes.length)return `<section class="hero"><div class="hero-text"><div class="hero-eyebrow">HIGEKIRI · VOICE ARCHIVE</div><h1>${E(tr('髭切的台词收藏'))}</h1><p>${E(tr('前往偏好设置，添加你喜欢的中文与日文台词。'))}</p>${button('去填写台词','quote-edit','','btn-primary')}</div><div class="hero-art"><span class="hero-art-inner">✿</span></div></section>`;
 const current=quoteReadout(quotes);return `<section class="hero hero-quotes"><div class="hero-text"><div class="hero-eyebrow">HIGEKIRI · VOICE ARCHIVE <span class="hero-eyebrow-star">✧</span></div><div class="hero-quote-stage" id="heroQuoteStage"><div class="hero-character-label">髭切 <span>ひげきり</span> <span class="hero-quote-label">${E(tr('台词收藏'))}</span></div><h1 id="heroQuoteText" lang="${current.lang==='zh'?settings.language:'ja'}">${E(current.text)}</h1><p class="hero-quote-meta" id="heroQuoteMeta">${current.lang==='zh'?'中文 · CHINESE':'日本語 · JAPANESE'} <span class="hero-quote-number">${String(current.index+1).padStart(2,'0')} / ${String(quotes.length).padStart(2,'0')}</span></p></div><div class="quote-controls"><div class="quote-language" role="group" aria-label="${E(tr('台词语言'))}"><button data-action="quote-lang" data-lang="zh" class="${state.quoteLang==='zh'?'active':''}" aria-pressed="${state.quoteLang==='zh'}">中文</button><button data-action="quote-lang" data-lang="ja" class="${state.quoteLang==='ja'?'active':''}" aria-pressed="${state.quoteLang==='ja'}">日本語</button></div><div class="quote-navigation"><button data-action="quote-prev" class="quote-icon" aria-label="上一句台词" title="上一句台词">‹</button><button data-action="quote-next" class="quote-icon" aria-label="下一句台词" title="下一句台词">›</button><button data-action="quote-pause" id="quotePauseButton" class="quote-icon quote-play" aria-label="${state.quotePaused?'播放轮播':'暂停轮播'}" title="${state.quotePaused?'播放轮播':'暂停轮播'}">${state.quotePaused?'▶':'Ⅱ'}</button></div><button data-action="quote-edit" class="quote-edit" title="在设置里编辑台词">✎ ${E(tr('编辑台词'))}</button></div><div class="quote-demo-hint">✧ ${E(tr('当前为原创示例台词（非官方），可在偏好设置替换。'))}</div><div class="hero-actions">${button(`${icon('plus',16)}${E(tr('新建角色'))}`,'new-oc','','btn-primary')}${button(`${icon('feather',16)}${E(tr('记下灵感'))}`,'new-idea')}</div></div><div class="hero-art"><span class="hero-art-inner">✿</span></div><span class="hero-vertical">物語の書庫</span></section>`;}
function stopQuoteRotation(){if(quoteInterval!==null){clearInterval(quoteInterval);quoteInterval=null}if(quoteSwapTimeout!==null){clearTimeout(quoteSwapTimeout);quoteSwapTimeout=null}}
function startQuoteRotation(){if(!settings.quoteAutoplay||state.quotePaused||matchMedia('(prefers-reduced-motion: reduce)').matches||!getHigekiriQuotes().length)return;quoteInterval=setInterval(()=>{if(document.visibilityState!=='visible'||document.getElementById('heroQuoteText')===null)return;advanceQuote(true)},5800)}
function animateQuote(){const stage=document.getElementById('heroQuoteStage'),text=document.getElementById('heroQuoteText'),meta=document.getElementById('heroQuoteMeta');const quotes=getHigekiriQuotes();if(!stage||!text||!meta||!quotes.length)return;if(quoteSwapTimeout!==null)clearTimeout(quoteSwapTimeout);stage.classList.add('is-leaving');quoteSwapTimeout=setTimeout(()=>{const q=quoteReadout(quotes);text.textContent=q.text;text.lang=q.lang==='zh'?settings.language:'ja';meta.innerHTML=(q.lang==='zh'?'中文 · CHINESE':'日本語 · JAPANESE')+` <span class="hero-quote-number">${String(q.index+1).padStart(2,'0')} / ${String(quotes.length).padStart(2,'0')}</span>`;document.querySelectorAll('.quote-language button').forEach(b=>{const active=b.dataset.lang===state.quoteLang;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});stage.classList.remove('is-leaving');quoteSwapTimeout=null},260)}
function advanceQuote(auto=false,direction=1){const q=getHigekiriQuotes();if(!q.length)return;if(auto){if(state.quoteLang==='zh'){state.quoteLang='ja'}else{state.quoteLang='zh';state.quoteIndex=(state.quoteIndex+1)%q.length}}else state.quoteIndex=(state.quoteIndex+direction+q.length)%q.length;animateQuote();if(!auto){if(quoteInterval!==null){clearInterval(quoteInterval);quoteInterval=null}startQuoteRotation()}}
function renderHome(){const stats=[{title:'OC设定',n:records.ocs.length,sub:'珍藏的角色',go:'ocs'},{title:'PARO记录',n:records.paro.length,sub:'平行世界的故事',go:'paro'},{title:'约稿存档',n:records.commissions.length,sub:'收集的画作',go:'commissions'},{title:'灵感随记',n:records.ideas.length,sub:'留住的瞬间',go:'ideas'}];const latest=[...TYPES.flatMap(type=>recentOf(type,4).map(v=>({...v,_type:type})))].sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')).slice(0,5);const due=records.commissions.filter(c=>c.dueDate&&!c.doneDate&&c.status!=='已完成').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,3);return `${quoteHero()}<div class="dashboard-counters">${stats.map(x=>`<div class="stat-card" data-nav="${x.go}" role="button" tabindex="0" style="cursor:pointer"><div class="stat-label">${E(tr(x.title))}</div><div class="stat-value">${x.n.toString().padStart(2,'0')}</div><div class="stat-sub">${E(tr(x.sub))}</div></div>`).join('')}</div><div class="dashboard-grid"><section class="dash-section"><div class="section-heading"><h2>${E(tr('最近珍藏'))}<small>RECENTLY SAVED</small></h2><button class="text-action" data-nav="ocs">${E(tr('查看角色'))} ${icon('chevron',14)}</button></div><div class="panel">${latest.length?`<div class="mini-list">${latest.map(x=>homeRecentRow(x,x._type)).join('')}</div>`:`${empty('还没有收藏的故事','从第一个角色开始，慢慢充实你的私人书阁。','new-oc','新建角色',true)}`}</div></section><section class="dash-section"><div class="section-heading"><h2>${E(tr('书阁便笺'))}<small>A LITTLE NOTE</small></h2></div><div class="panel panel-inner"><div style="text-align:center;color:var(--gold);font-size:30px;margin-bottom:10px">❀</div><h3 style="text-align:center;font-size:16px;margin-bottom:10px">${E(tr('今天，也收集一点喜欢。'))}</h3><p class="muted" style="text-align:center;font-size:12px;margin-bottom:18px">${E(tr('所有文字和图片仅保存在当前设备。记得偶尔去设置里导出一份备份喔。'))}</p><div style="display:flex;justify-content:center">${button(`${icon('download',15)}${E(tr('备份我的书阁'))}`,'export-backup')}</div>${due.length?`<div class="welcome-note"><strong>${E(tr('预计完成的约稿'))}</strong>${due.map(d=>`<div style="margin-top:7px">${E(d.title)} · ${E(day(d.dueDate))}</div>`).join('')}</div>`:''}<div class="welcome-note">${E(tr('小提示：在 OC 档案、PARO 和灵感页都可以一键复制文字；约稿存档可按顺序保存草稿、修改稿与高清成图。'))}</div></div></section></div>`}
function sectionMeta(type){return {ocs:{en:'CHARACTER ARCHIVE',title:'OC设定',subtitle:'收好每一位角色的名字、模样与故事。',action:'new-oc',label:'新增角色',emptyTitle:'第一位角色，正在等你',emptyDesc:'添加角色立绘、身世、设定和不同世界线。'},paro:{en:'ALTERNATE WORLDS',title:'PARO记录',subtitle:'同一个灵魂，也可以拥有无数种相遇。',action:'new-paro',label:'新建PARO',emptyTitle:'在这里，写下另一种可能',emptyDesc:'记录平行设定、故事片段和突发奇想的世界线。'},commissions:{en:'ART COLLECTION',title:'约稿存档',subtitle:'从第一笔草稿，到值得珍藏的高清成图。',action:'new-commission',label:'新建约稿',emptyTitle:'为喜欢的画作留个位置',emptyDesc:'上传每版草稿、修改过程、高清成图与画中的小故事。'},ideas:{en:'INSPIRATION NOTES',title:'灵感随记',subtitle:'灵感有时很轻，写下来就不会散了。',action:'new-idea',label:'新建灵感',emptyTitle:'从一句话，开始新的故事',emptyDesc:'随手记下剧情、台词、画面或突然想到的点子。'}}[type]}
function sortedList(type){let q=state.query.trim().toLocaleLowerCase();let arr=[...records[type]];if(q)arr=arr.filter(x=>[x.title,x.name,x.world,x.story,x.content,x.background,x.description,x.theme].some(y=>String(y||'').toLocaleLowerCase().includes(q)));if(state.sort==='old')arr.sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||''));else if(state.sort==='name')arr.sort((a,b)=>(a.title||a.name||'').localeCompare(b.title||b.name||'','zh-CN'));else arr.sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));return arr}
function renderCollection(type){const m=sectionMeta(type),arr=sortedList(type);const control=`<div class="toolbar"><label class="search-field">${icon('search',17)}<input id="collectionSearch" type="search" value="${E(state.query)}" placeholder="${E(tr('搜索名称、世界观或内容…'))}" aria-label="${E(tr('搜索'))}" /></label><select id="collectionSort" class="select" aria-label="排序"><option value="recent" ${state.sort==='recent'?'selected':''}>${E(tr('最近修改'))}</option><option value="old" ${state.sort==='old'?'selected':''}>${E(tr('创建时间'))}</option><option value="name" ${state.sort==='name'?'selected':''}>${E(tr('名称排序'))}</option></select>${type==='ocs'?`<div class="display-switch" aria-label="展示方式">${['grid','list','table'].map(v=>`<button aria-label="${E(v)}" class="${state.display===v?'selected':''}" data-action="set-view" data-view="${v}" title="${E(tr(v==='grid'?'卡片':v==='list'?'列表':'表格'))}">${icon(v,17)}</button>`).join('')}</div>`:''}</div>`;let body='';if(arr.length){if(type==='ocs'&&state.display==='table')body=renderTable(arr,type);else if(type==='ocs'&&state.display==='list')body=`<div class="item-list">${arr.map(x=>renderListEntry(x,type)).join('')}</div>`;else body=`<div class="item-grid">${arr.map(x=>renderCard(x,type)).join('')}</div>`}else body=empty(state.query?'没有找到匹配的记录':m.emptyTitle,state.query?'试试其他关键词，或清空搜索。':m.emptyDesc,state.query?'':m.action,m.label);return `${rowHeader(m.en,m.title,m.subtitle,m.action,m.label)}${control}${body}`}
function cardCover(r,type){const media=type==='ocs'?r.coverId:type==='commissions'?(r.stages?.find(x=>x.kind==='final')?.mediaId||r.stages?.at(-1)?.mediaId):null;const text=type==='ocs'?'PERSONA':type==='commissions'?'ARTWORK':type==='paro'?'PARO':'IDEA';return `<div class="item-cover">${media?img(media,r.name||r.title):`<span class="placeholder-symbol">${type==='ideas'?'✎':type==='paro'?'☯':type==='commissions'?'❀':'✿'}</span>`}<span class="corner-label">${text}</span></div>`}
function renderCard(r,type){return `<article class="item-card">${cardCover(r,type)}<div class="item-card-body"><h3 title="${E(r.name||r.title||'未命名')}">${E(r.name||r.title||'未命名')}</h3><div class="card-meta">${E(type==='ocs'?(r.world||tr('尚未填写世界观')):type==='commissions'?((r.stages?.length||0)+' 张过程图 · '+(r.status||'作品存档')):type==='paro'?(r.theme||tr('另一种世界线')):short(r.content,35)||tr('随手写下的灵感'))}</div><div class="card-bottom"><span>${E(day(r.updatedAt))}</span><button data-action="detail" data-type="${type}" data-id="${E(r.id)}">${E(tr('展开查看'))} ${icon('chevron',12)}</button></div></div></article>`}
function renderListEntry(r,type){const cover=type==='ocs'?r.coverId:null;return `<button class="list-entry" data-action="detail" data-type="${type}" data-id="${E(r.id)}"><span class="list-cover">${cover?img(cover,r.name):'✿'}</span><span class="list-body"><strong>${E(r.name||r.title)}</strong><small>${E(r.world||r.theme||short(r.content,45)||'—')}</small></span><span class="list-tail">${E(day(r.updatedAt))}</span>${icon('chevron',16)}</button>`}
function renderTable(arr,type){return `<div class="table-frame"><table class="data-table"><thead><tr><th>${E(tr('名称'))}</th><th>${E(tr('世界观'))}</th><th>${E(tr('上次修改'))}</th><th>${E(tr('操作'))}</th></tr></thead><tbody>${arr.map(r=>`<tr><td><strong>${E(r.name)}</strong></td><td>${E(r.world||'—')}</td><td>${E(day(r.updatedAt))}</td><td><button data-action="detail" data-id="${E(r.id)}" data-type="${type}">${E(tr('查看'))} →</button></td></tr>`).join('')}</tbody></table></div>`}
function findRecord(type,id){return records[type]?.find(r=>r.id===id)}
function renderDetail(type,id){const r=findRecord(type,id);if(!r)return `<div>${E(tr('记录不存在'))}</div>`;if(type==='ocs')return detailOC(r);if(type==='commissions')return detailCommission(r);if(type==='paro')return detailParo(r);return detailIdea(r)}
function detailTop(type,r,title,subtitle){return `<button class="detail-back" data-action="back-list">${icon('back',16)}${E(tr('返回'))} ${E(tr(sectionMeta(type).title))}</button><div class="detail-header"><div><div class="eyebrow">${sectionMeta(type).en}</div><h1>${E(title||'未命名')}</h1><p>${E(subtitle||'')} <span style="padding:0 7px;color:var(--border-strong)">·</span> ${E(tr('最近修改'))} ${E(day(r.updatedAt))}</p></div><div class="header-actions">${button(`${icon('copy',15)}${E(tr('复制内容'))}`,'copy-record',`data-type="${type}" data-id="${E(r.id)}"`)}${button(`${icon('edit',15)}${E(tr('编辑'))}`,'edit-record',`data-type="${type}" data-id="${E(r.id)}"`,'btn-primary')}${button(`${icon('trash',15)}`,'delete-record',`data-type="${type}" data-id="${E(r.id)}" aria-label="删除"`,'btn-danger btn-icon')}</div></div>`}
function fact(label,value){return value?`<div><div class="fact-label">${E(tr(label))}</div><div class="fact-value">${E(value)}</div></div>`:''}
function panel(title,html){return `<div class="detail-panel"><h2>${E(tr(title))}</h2>${html||`<p class="muted small no-margin">${E(tr('暂时还没有填写。'))}</p>`}</div>`}
function detailOC(r){const personFacts=[['世界观',r.world],['年龄',r.age],['生日',r.birthday],['性别',r.gender],['代称',r.pronouns],['身高',r.height],['体型',r.build],['职业 / 身份',r.career],['能力',r.abilities]];const charFacts=[['外貌特征',r.appearance],['性格',r.personality],['喜好',r.likes]];const gallery=r.gallery||[],aus=r.aus||[],extras=r.extras||[],hist=r.history||[];let story=(r.background&&sanitizeRich(r.background))||'';return `${detailTop('ocs',r,r.name,r.world)}<div class="detail-grid"><div><div class="detail-photo">${r.coverId?img(r.coverId,r.name,'',true):'<span class="placeholder-symbol">✿</span>'}</div>${r.coverId?`<div style="margin-top:8px;text-align:right"><button class="text-action" data-action="view-media" data-media="${E(r.coverId)}" data-caption="${E(r.name)}">${icon('expand',14)}${E(tr('打开大图'))}</button></div>`:''}</div><div class="detail-info">${panel('人物资料',`<div class="fact-grid">${personFacts.map(x=>fact(...x)).join('')||'<span class="muted">—</span>'}</div>`)}${panel('外貌与设定',`<div class="fact-grid">${charFacts.map(x=>fact(...x)).join('')||'<span class="muted">—</span>'}</div>`)}${panel('角色故事',story?`<div class="rich-prose">${story}</div>`:'')}</div></div><div class="detail-bottom">${aus.length?panel('世界线 / AU',aus.map((a,i)=>`<div style="${i?'border-top:1px solid var(--border);padding-top:13px;margin-top:13px':''}"><strong>${E(a.name||'未命名 AU')}</strong><div class="prose" style="margin-top:7px">${E(a.description||'')}</div></div>`).join('')):''}${extras.length?panel('自定义字段',`<div class="fact-grid">${extras.map(x=>fact(x.key||'其他',x.value)).join('')}</div>`):''}${gallery.length?panel('图像画廊',`<div class="photo-grid">${gallery.map((g,i)=>`<div class="photo-tile"><button data-action="view-media" data-media="${E(g.mediaId)}" data-caption="${E(g.caption||('图片 '+(i+1)))}">${img(g.mediaId,g.caption||r.name)}</button><div class="photo-caption">${E(g.group||'插画')} · ${E(g.caption||'未命名')}</div></div>`).join('')}</div>`):''}${hist.length?panel('修改记录',hist.map((h,i)=>`<div class="history-item"><div><strong class="small">${E(day(h.savedAt))}</strong><br/><small>${E(tr('历史版本'))} ${hist.length-i}</small></div>${button(E(tr('恢复此版本')),'restore-version',`data-id="${E(r.id)}" data-index="${i}"`,'btn-sm')}</div>`).join('')):''}</div>`}
function detailCommission(r){const stages=r.stages||[];const facts=[['当前状态',r.status],['下单日期',r.orderDate],['预定完成',r.dueDate],['完成日期',r.doneDate],['金额',r.amount]];return `${detailTop('commissions',r,r.title,r.status||'')}<div class="detail-bottom" style="margin-top:0">${panel('作品资料',`<div class="fact-grid">${facts.map(([a,b])=>fact(a,a==='当前状态'||a==='金额'?b:b?day(b):'')).join('')}</div>${r.description?`<hr/><div class="fact-label">${E(tr('约稿需求 / 灵感来源'))}</div><div class="prose">${E(r.description)}</div>`:''}`)}${panel('约稿过程',stages.length?`<div class="timeline">${stages.map((g,i)=>`<div class="timeline-entry"><div class="timeline-card"><button class="timeline-img" data-action="view-media" data-media="${E(g.mediaId)}" data-caption="${E(g.label||'草稿')}" aria-label="查看高清图片">${img(g.mediaId,g.label||'稿件')}</button><div><span class="pill ${g.kind==='final'?'accent':''}">${E(tr(g.kind==='final'?'高清成图':'草稿版本'))} · ${String(i+1).padStart(2,'0')}</span><h3>${E(g.label||('第 '+(i+1)+' 版'))}</h3><p>${E(g.note||'')}</p><div style="margin-top:14px"><button class="text-action" data-action="view-media" data-media="${E(g.mediaId)}" data-caption="${E(g.label||'稿件')}">${icon('expand',14)}${E(tr('打开大图 / 下载原图'))}</button></div></div></div></div>`).join('')}</div>`:`<p class="muted small">${E(tr('还没添加过程图。编辑存档时，可以依次上传每一版草稿和高清成图。'))}</p>`)}${panel('作品背后的小故事',r.story?`<div class="story-paper"><div class="prose">${E(r.story)}</div></div>`:'')}</div>`}
function detailParo(r){return `${detailTop('paro',r,r.title,r.theme||r.world||'')}<div class="detail-bottom" style="margin-top:0">${(r.theme||r.world||r.characters)?panel('基本设定',`<div class="fact-grid">${fact('主题',r.theme)}${fact('世界观',r.world)}${fact('登场角色',r.characters)}</div>`):''}${panel('平行世界的故事',r.content?`<div class="prose">${E(r.content)}</div>`:'')}</div>`}
function detailIdea(r){return `${detailTop('ideas',r,r.title,r.category||'')}<div class="detail-bottom" style="margin-top:0">${panel('灵感随记',`<div class="story-paper"><div class="prose">${E(r.content||'')}</div></div>`)}</div>`}
function inputField(label,key,value='',placeholder='',span=false,type='text',hint=''){return `<div class="field ${span?'span-2':''}"><label for="edit-${E(key)}">${E(tr(label))}</label>${type==='textarea'?`<textarea id="edit-${E(key)}" data-field="${E(key)}" placeholder="${E(tr(placeholder))}" rows="4">${E(value)}</textarea>`:`<input id="edit-${E(key)}" type="${type}" data-field="${E(key)}" value="${E(value)}" placeholder="${E(tr(placeholder))}" ${type==='date'?'':''}/>`}${hint?`<span class="hint">${E(tr(hint))}</span>`:''}</div>`}
function sectionHead(name){return `<div class="form-section-heading">✦ ${E(tr(name))}</div>`}
function uploadBox(target,multiple,label){return `<label class="upload-box">${icon('upload',22)}<strong class="small">${E(tr(label))}</strong><small>${E(tr('支持手机相册 / 电脑文件 · 保留上传的原图'))}</small><input aria-label="${E(tr(label))}" type="file" accept="image/*" data-upload="${target}" ${multiple?'multiple':''}/></label>`}
function editorMedia(arr,kind){return `<div class="editor-media-grid">${arr.map((g,i)=>{const isStages=kind==='stages',isGallery=kind==='gallery';return `<div class="editor-media"><div class="editor-media-thumb">${img(g.mediaId,g.label||g.caption||'图片')}</div>${isStages?`<select data-stage-index="${i}" data-stage-field="kind"><option value="draft" ${g.kind!=='final'?'selected':''}>${E(tr('草稿 / 修改稿'))}</option><option value="final" ${g.kind==='final'?'selected':''}>${E(tr('高清成图'))}</option></select><input data-stage-index="${i}" data-stage-field="label" value="${E(g.label||'')}" placeholder="${E(tr('版本名称'))}"/><input data-stage-index="${i}" data-stage-field="note" value="${E(g.note||'')}" placeholder="${E(tr('这一版的变化 / 备注'))}"/>`:`<input data-gallery-index="${i}" data-gallery-field="group" value="${E(g.group||'插画')}" placeholder="${E(tr('分组'))}"/><input data-gallery-index="${i}" data-gallery-field="caption" value="${E(g.caption||'')}" placeholder="${E(tr('图片说明'))}"/>`}<div class="editor-media-actions"><button data-action="reorder-media" data-kind="${kind}" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="前移">←</button><button data-action="reorder-media" data-kind="${kind}" data-index="${i}" data-direction="1" ${i===arr.length-1?'disabled':''} aria-label="后移">→</button><button class="danger" data-action="remove-media" data-kind="${kind}" data-index="${i}">${E(tr('移除'))}</button></div></div>`}).join('')}</div>`}
function renderOCEditor(r){return `${sectionHead('角色档案')}<div class="form-grid">${inputField('角色名称 *','name',r.name,'例如：春野 明')}${inputField('所属世界观','world',r.world,'故事发生在哪里？')}${inputField('年龄','age',r.age)}${inputField('生日','birthday',r.birthday,'例如 3月21日')}${inputField('性别','gender',r.gender)}${inputField('代称','pronouns',r.pronouns)}${inputField('身高','height',r.height)}${inputField('体型','build',r.build)}${inputField('职业 / 身份','career',r.career)}${inputField('能力','abilities',r.abilities)}${inputField('外貌特征','appearance',r.appearance,'发色、瞳色、衣着……',true,'textarea')}${inputField('性格','personality',r.personality,'',true,'textarea')}${inputField('喜好','likes',r.likes,'',true,'textarea')}</div>${sectionHead('封面 / 立绘')}${r.coverId?`<div style="display:flex;gap:14px;align-items:center;margin-bottom:12px"><div class="mini-icon" style="width:83px;height:83px">${img(r.coverId,r.name)}</div>${button(`${icon('trash',14)}${E(tr('移除封面'))}`,'remove-cover','','btn-sm')}</div>`:''}${uploadBox('cover',false,'上传角色封面 / 立绘')}${sectionHead('角色背景故事')}<div class="field"><label>${E(tr('富文本设定'))}</label><div class="rich-toolbar"><button data-richcmd="bold" title="加粗"><b>B</b></button><button data-richcmd="italic" title="斜体"><i>I</i></button><button data-richcmd="underline" title="下划线"><u>U</u></button><button data-richcmd="insertUnorderedList" title="项目符号">☷</button><button data-richcmd="formatBlock" data-value="h3" title="小标题">H3</button></div><div class="rich-editor" contenteditable="true" id="richBackground" data-placeholder="写下角色的来历、经历和故事……">${sanitizeRich(r.background||'')}</div><span class="hint">${E(tr('选中文字后可使用上方工具；每次保存修改都会保留旧版文字。'))}</span></div>${sectionHead('世界线 / AU')}${(r.aus||[]).map((a,i)=>`<div class="array-item"><div class="array-item-head"><strong>AU ${i+1}</strong><button data-action="array-remove" data-kind="aus" data-index="${i}">${E(tr('删除'))}</button></div><div class="form-grid">${arrayInput('aus',i,'name','世界线名称',a.name)}${arrayInput('aus',i,'description','世界线设定',a.description,true)}</div></div>`).join('')}${button(`${icon('plus',15)}${E(tr('添加世界线'))}`,'array-add','data-kind="aus"','btn-sm')}${sectionHead('自定义字段')}${(r.extras||[]).map((a,i)=>`<div class="array-item"><div class="array-item-head"><strong>${E(tr('补充资料'))} ${i+1}</strong><button data-action="array-remove" data-kind="extras" data-index="${i}">${E(tr('删除'))}</button></div><div class="form-grid">${arrayInput('extras',i,'key','字段名称',a.key)}${arrayInput('extras',i,'value','字段内容',a.value)}</div></div>`).join('')}${button(`${icon('plus',15)}${E(tr('添加字段'))}`,'array-add','data-kind="extras"','btn-sm')}${sectionHead('图像画廊')}${editorMedia(r.gallery||[],'gallery')}${uploadBox('gallery',true,'添加插画 / 立绘 / 其他图片')}`}
function arrayInput(kind,i,field,label,value='',large=false){return `<div class="field ${large?'span-2':''}"><label>${E(tr(label))}</label>${large?`<textarea data-array="${kind}" data-array-index="${i}" data-array-field="${field}" rows="3">${E(value)}</textarea>`:`<input data-array="${kind}" data-array-index="${i}" data-array-field="${field}" value="${E(value||'')}" />`}</div>`}
function renderCommissionEditor(r){return `${sectionHead('作品资料')}<div class="form-grid">${inputField('作品名称 *','title',r.title,'例如：花下的约定')}${inputField('当前状态','status',r.status,'例如：已完成')}${inputField('下单日期','orderDate',r.orderDate,'',false,'date')}${inputField('预定完成','dueDate',r.dueDate,'',false,'date')}${inputField('完成日期','doneDate',r.doneDate,'',false,'date')}${inputField('金额（可选）','amount',r.amount,'例如：¥200')}${inputField('约稿需求 / 画面设定','description',r.description,'画面的构思、要求、参考方向……',true,'textarea')}</div>${sectionHead('草稿与高清成图')}<p class="muted small">${E(tr('依次添加每一版草稿、修改稿和最终成图；上传后可调整先后顺序，点击存档中的图片可以看原图。'))}</p>${editorMedia(r.stages||[],'stages')}${uploadBox('stages',true,'添加草稿、过程图或高清成图')}${sectionHead('作品背后的小故事')}<div class="form-grid">${inputField('画作故事','story',r.story,'这张画里发生了什么？为什么想约这幅画？',true,'textarea')}</div>`}
function renderParoEditor(r){return `${sectionHead('PARO / 平行世界设定')}<div class="form-grid">${inputField('标题 *','title',r.title,'例如：现代学园 PARO')}${inputField('主题','theme',r.theme,'例如：校园 / 奇幻 / 架空')}${inputField('世界观','world',r.world,'时代、地点、背景……')}${inputField('登场角色','characters',r.characters,'自由填写人名',true)}${inputField('设定与故事','content',r.content,'写下这条世界线的设定、片段和故事……',true,'textarea')}</div>`}
function renderIdeaEditor(r){return `${sectionHead('随手写下来')}<div class="form-grid">${inputField('标题 *','title',r.title,'给这段灵感起个名字')}${inputField('类别（可选）','category',r.category,'剧情 / 台词 / 画面 / 其他')}${inputField('正文','content',r.content,'一句台词、一个场景、一个突然冒出的念头……',true,'textarea')}</div>`}
function startEditor(type,id=null){const original=id?findRecord(type,id):null;state.editor=original?structuredClone(original):{id:uid(),createdAt:now(),updatedAt:now(),...(type==='ocs'?{name:'',gallery:[],aus:[],extras:[],history:[]}:type==='commissions'?{title:'',stages:[]}:type==='paro'?{title:''}:{title:''})};state.editorType=type;state.editorId=id;renderEditor(true)}
function renderEditor(focus=false){const r=state.editor,type=state.editorType;const title=(state.editorId?tr('编辑'):tr('新建'))+' · '+tr(sectionMeta(type).title);const inner=type==='ocs'?renderOCEditor(r):type==='commissions'?renderCommissionEditor(r):type==='paro'?renderParoEditor(r):renderIdeaEditor(r);const oldScroll=document.querySelector('.modal-body')?.scrollTop||0;document.getElementById('modalRoot').innerHTML=`<div class="modal-overlay" data-action="overlay-close"><div class="modal-dialog wide" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="modal-header"><div><div class="eyebrow">${E(sectionMeta(type).en)}</div><h2>${E(title)}</h2><p>${E(tr('所有修改将保存在当前设备中'))}</p></div><button class="icon-button" data-action="close-editor" title="关闭" aria-label="关闭">${icon('close',21)}</button></div><div class="modal-body">${inner}</div><div class="modal-footer">${button(E(tr('取消')),'close-editor')}${button(`${icon('save',15)}${E(tr('保存到此设备'))}`,'save-editor','','btn-primary')}</div></div></div>`;document.body.style.overflow='hidden';document.querySelector('.modal-body').scrollTop=oldScroll;hydrateImages(document.getElementById('modalRoot'));if(focus)document.querySelector('.modal-body [data-field]')?.focus()}
function collectEditor(){if(!state.editor)return;const root=document.getElementById('modalRoot');root.querySelectorAll('[data-field]').forEach(el=>{state.editor[el.dataset.field]=el.value});if(state.editorType==='ocs'){const e=root.querySelector('#richBackground');if(e)state.editor.background=sanitizeRich(e.innerHTML)}root.querySelectorAll('[data-array-index]').forEach(el=>{const {array, arrayIndex,arrayField}=el.dataset;if(state.editor[array]?.[+arrayIndex])state.editor[array][+arrayIndex][arrayField]=el.value});root.querySelectorAll('[data-gallery-index]').forEach(el=>{const o=state.editor.gallery?.[+el.dataset.galleryIndex];if(o)o[el.dataset.galleryField]=el.value});root.querySelectorAll('[data-stage-index]').forEach(el=>{const o=state.editor.stages?.[+el.dataset.stageIndex];if(o)o[el.dataset.stageField]=el.value})}
function closeEditor(){state.editor=null;state.editorType=null;state.editorId=null;document.getElementById('modalRoot').innerHTML='';document.body.style.overflow=''}
async function saveEditor(){collectEditor();const r=state.editor,type=state.editorType;const mainName=type==='ocs'?r.name:r.title;if(!mainName?.trim()){toast('请先填写名称 / 标题',true);document.querySelector('.modal-body [data-field="'+(type==='ocs'?'name':'title')+'"]')?.focus();return}r.updatedAt=now();if(state.editorId&&type==='ocs'){const old=findRecord(type,state.editorId);if(old){const snap=structuredClone(old);delete snap.history;r.history=[{savedAt:old.updatedAt||now(),snapshot:snap},...(old.history||[])].slice(0,15)}}await putItem('entries',{key:type+':'+r.id,type,data:r});await refreshRecords();closeEditor();state.section=type;state.detailId=r.id;render();window.scrollTo({top:0});toast(tr('已保存'))}
async function removeRecord(type,id){const r=findRecord(type,id);if(!r)return;if(!confirm(`确认删除「${r.name||r.title}」吗？\n删除后不能在网页内撤销，已导出的备份不受影响。`))return;await removeItem('entries',type+':'+id);await refreshRecords();state.detailId=null;render();toast('已删除记录')}
async function restoreVersion(id,index){const r=findRecord('ocs',id),h=r?.history?.[index];if(!h)return;if(!confirm('恢复此历史版本？当前版本也会保存到历史中。'))return;const snapshot=structuredClone(h.snapshot);const nowSnap=structuredClone(r);delete nowSnap.history;const next={...snapshot,id,history:[{savedAt:now(),snapshot:nowSnap},...r.history.filter((_,i)=>i!==index)].slice(0,15),updatedAt:now()};await putItem('entries',{key:'ocs:'+id,type:'ocs',data:next});await refreshRecords();render();toast('已恢复历史版本')}
function recordText(type,r){if(type==='ocs'){let text=[`【${r.name||'OC设定'}】`,r.world&&`世界观：${r.world}`,...[['年龄',r.age],['生日',r.birthday],['性别',r.gender],['代称',r.pronouns],['身高',r.height],['体型',r.build],['外貌',r.appearance],['性格',r.personality],['喜好',r.likes],['职业 / 身份',r.career],['能力',r.abilities]].filter(x=>x[1]).map(([a,b])=>`${a}：${b}`),r.background&&`\n【背景故事】\n${stripHtml(r.background)}`,...(r.aus||[]).map(x=>`\n【${x.name||'AU'}】\n${x.description||''}`),...(r.extras||[]).map(x=>`${x.key||'其他'}：${x.value||''}`)].filter(Boolean);return text.join('\n')}if(type==='commissions')return [`【${r.title}】`,r.description&&`画面设定：${r.description}`,r.story&&`\n【作品背后的小故事】\n${r.story}`].filter(Boolean).join('\n');if(type==='paro')return [`【${r.title}】`,r.theme&&`主题：${r.theme}`,r.world&&`世界观：${r.world}`,r.characters&&`登场角色：${r.characters}`,r.content&&`\n${r.content}`].filter(Boolean).join('\n');return [r.title,r.content].filter(Boolean).join('\n\n')}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板')}catch{const textarea=document.createElement('textarea');textarea.value=text;textarea.style.position='fixed';textarea.style.opacity='0';document.body.appendChild(textarea);textarea.select();document.execCommand('copy');textarea.remove();toast('已复制到剪贴板')}}
function renderSettings(){return `${rowHeader('PERSONALIZE YOUR SPACE','偏好设置','让这一方小小书阁，成为你喜欢的样子。')}<div class="settings-layout"><div><section class="settings-section"><h2>${E(tr('书阁的名字与模样'))}</h2><p>${E(tr('这些设置仅影响当前设备的显示。'))}</p><div class="field"><label>${E(tr('站点名称'))}</label><input class="setting-input" id="siteTitle" maxlength="60" value="${E(settings.title)}" placeholder="maki的工作台"/></div><div class="settings-item"><div><div class="settings-item-label">${E(tr('个人头像'))}</div><div class="settings-item-sub">${E(tr('上传一张你喜欢的图片'))}</div></div><div style="display:flex;align-items:center;gap:12px"><div class="setting-avatar">${settings.avatarId?img(settings.avatarId,'头像'):'✿'}</div><label class="btn btn-sm" style="position:relative">${icon('upload',14)}${E(tr('更换'))}<input type="file" accept="image/*" data-upload="avatar" style="position:absolute;inset:0;opacity:0;width:100%;cursor:pointer"/></label></div></div><div class="settings-item"><div><div class="settings-item-label">${E(tr('语言'))}</div><div class="settings-item-sub">${E(tr('页面界面的语言'))}</div></div><select id="settingsLang" class="select"><option value="zh-Hans" ${settings.language==='zh-Hans'?'selected':''}>简体中文</option><option value="zh-Hant" ${settings.language==='zh-Hant'?'selected':''}>繁體中文</option></select></div></section><section class="settings-section"><h2>${E(tr('外观与文字'))}</h2><p>${E(tr('以和纸、朱色与古典纹样为灵感，挑选你的配色。'))}</p><div class="settings-item-label">${E(tr('主题色'))}</div><div class="palette-grid">${COLORS.map(c=>`<button class="swatch ${settings.accent===c.color?'selected':''}" data-action="set-accent" data-color="${c.color}" aria-label="${E(c.name)}" title="${E(c.name)}"><span style="background:${c.color}"></span></button>`).join('')}<label title="自选颜色" style="position:relative;display:grid;place-items:center;cursor:pointer;width:40px;height:40px;border-radius:50%;border:1px dashed var(--border-strong);color:var(--muted)">✎<input type="color" id="customAccent" value="${E(settings.accent)}" style="position:absolute;inset:0;opacity:0;width:100%;height:100%;cursor:pointer" aria-label="自定义主题色"/></label></div><div class="settings-item"><div><div class="settings-item-label">${E(tr('明暗模式'))}</div><div class="settings-item-sub">${E(tr('白日和纸 / 夜间墨色'))}</div></div><select id="settingsTheme" class="select"><option value="light" ${settings.theme==='light'?'selected':''}>${E(tr('浅色模式'))}</option><option value="dark" ${settings.theme==='dark'?'selected':''}>${E(tr('深色模式'))}</option></select></div><div class="settings-item"><div><div class="settings-item-label">${E(tr('字体'))}</div><div class="settings-item-sub">${E(tr('可切换四种字体风格，显示效果依赖设备字体'))}</div></div><select id="settingsFont" class="select"><option value="sans" ${settings.font==='sans'?'selected':''}>清爽黑体</option><option value="serif" ${settings.font==='serif'?'selected':''}>典雅宋体</option><option value="kai" ${settings.font==='kai'?'selected':''}>书卷楷体</option><option value="rounded" ${settings.font==='rounded'?'selected':''}>柔和圆体</option></select></div></section><section class="settings-section quote-settings" id="higekiriQuoteSettings"><div class="eyebrow">HIGEKIRI · BILINGUAL LINES</div><h2>${E(tr('髭切 · 中日台词'))}</h2><p>${E(tr('每组填写一句中文和对应的日语；首页会自动淡入淡出、依次轮播两种语言。'))}</p><p class="quote-warning">✧ ${E(tr('预置内容是原创示例，不是《刀剑乱舞》的官方台词。请自行替换成你喜欢的原句。'))}</p>${(Array.isArray(settings.higekiriQuotes)?settings.higekiriQuotes:DEFAULT_HIGEKIRI_QUOTES).map((pair,i)=>`<div class="quote-setting-pair"><div class="quote-setting-head"><strong>${E(tr('第'))} ${i+1} ${E(tr('组'))}</strong><button data-action="quote-remove" data-index="${i}" class="quote-remove" ${settings.higekiriQuotes.length<=1?'disabled':''} aria-label="${E(tr('删除这组台词'))}">${icon('trash',14)} ${E(tr('删除'))}</button></div><div class="field"><label for="quoteZh${i}">中文台词</label><textarea id="quoteZh${i}" data-quote-input data-quote-index="${i}" data-quote-lang="zh" rows="2" maxlength="420" placeholder="请填写中文台词">${E(pair.zh||'')}</textarea></div><div class="field"><label for="quoteJa${i}">日本語台詞</label><textarea id="quoteJa${i}" data-quote-input data-quote-index="${i}" data-quote-lang="ja" rows="2" maxlength="420" placeholder="日本語のセリフを入力">${E(pair.ja||'')}</textarea></div></div>`).join('')}<div class="quote-settings-bottom">${button(`${icon('plus',15)}${E(tr('添加一组台词'))}`,'quote-add','','btn-sm')}<label class="quote-autoplay-checkbox"><input type="checkbox" id="quoteAutoplay" ${settings.quoteAutoplay?'checked':''}/> ${E(tr('首页自动轮播'))}</label></div><p class="tiny muted">${E(tr('台词保存到此设备的本地数据中，并包含在 ZIP 完整备份内。离开输入框后自动保存。'))}</p></section></div><div><section class="settings-section"><h2>${E(tr('数据与备份'))}</h2><p>${E(tr('无账号、无云端：资料直接保存在浏览器的 IndexedDB 中。'))}</p><div class="backup-info"><strong>${E(tr('关于你的资料'))}</strong><div>✦ ${E(tr('每台设备的数据相互独立，不自动同步。'))}</div><div>✦ ${E(tr('导出的 ZIP 包含设定文字、草稿和高清原图。'))}</div><div>✦ ${E(tr('清除浏览器网站数据、使用无痕模式或卸载浏览器可能导致资料丢失。'))}</div><div>✦ ${E(tr('建议每次重要修改后导出备份，另存到设备文件夹或网盘。'))}</div></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:18px">${button(`${icon('download',15)}${E(tr('导出完整备份'))}`,'export-backup','','btn-primary')}${button(`${icon('upload',15)}${E(tr('导入备份'))}`,'import-backup')}</div><p class="tiny muted" style="margin:13px 0 0">${E(tr('导入会替换此设备上的所有记录。导入前请先导出现有内容。'))}</p></section><section class="settings-section"><h2>${E(tr('关于本地存储'))}</h2><p>${E(tr('不上传资料至服务器，图片保留原文件。'))}</p><div class="settings-item"><span class="settings-item-label">${E(tr('OC设定'))}</span><strong>${records.ocs.length}</strong></div><div class="settings-item"><span class="settings-item-label">${E(tr('PARO记录'))}</span><strong>${records.paro.length}</strong></div><div class="settings-item"><span class="settings-item-label">${E(tr('约稿存档'))}</span><strong>${records.commissions.length}</strong></div><div class="settings-item"><span class="settings-item-label">${E(tr('灵感随记'))}</span><strong>${records.ideas.length}</strong></div><div class="settings-item"><span class="settings-item-label">${E(tr('已关联的图片'))}</span><strong>${mediaCount()}</strong></div><div style="font-size:11px;color:var(--muted);margin-top:21px" id="storageEstimate">${E(tr('正在读取存储空间信息…'))}</div></section><section class="settings-section" style="border-style:dashed"><div class="eyebrow">A SMALL REMINDER</div><p class="no-margin" style="font-size:13px">${E(tr('你写下的每一种可能，都值得被好好收藏。'))} ✿</p></section></div></div>`}
async function loadStorageEstimate(){try{const estimate=await navigator.storage?.estimate?.();let el=document.getElementById('storageEstimate');if(!el||!estimate)return;const mb=x=>(x/1024/1024).toFixed(1);el.textContent=`${tr('浏览器估计用量')} ${mb(estimate.usage||0)} MB / ${tr('可用配额约')} ${mb(estimate.quota||0)} MB`; }catch{}}
async function resizeThumbnail(blob){try{let bitmap=await createImageBitmap(blob);let w=bitmap.width,h=bitmap.height;if(!w||!h)return null;const scale=Math.min(1,800/Math.max(w,h));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));canvas.getContext('2d',{alpha:true}).drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.8))}catch{return null}}
async function addUploadedFiles(input){const files=Array.from(input.files||[]);if(!files.length)return;const target=input.dataset.upload;const isAvatar=target==='avatar';if(!isAvatar)collectEditor();if(files.some(f=>!f.type.startsWith('image/'))){toast('请选择图片文件',true);return}if(files.some(f=>f.size>100*1024*1024)){toast('单张图片请小于 100 MB，以免浏览器内存不足',true);return}if(files.length>60){toast('请分批上传，每次不超过 60 张图片',true);return}input.disabled=true;try{for(let f of files){const id=uid();let thumb=await resizeThumbnail(f);await putItem('media',{id,blob:f,thumb,name:f.name,mime:f.type||'application/octet-stream',size:f.size,createdAt:now()});if(isAvatar){settings.avatarId=id;await saveSettings()}else if(target==='cover')state.editor.coverId=id;else if(target==='gallery'){state.editor.gallery??=[];state.editor.gallery.push({mediaId:id,group:'插画',caption:f.name.replace(/\.[^.]+$/,'')})}else if(target==='stages'){state.editor.stages??=[];state.editor.stages.push({mediaId:id,kind:'draft',label:`草稿 ${String(state.editor.stages.length+1).padStart(2,'0')}`,note:''})}}if(isAvatar)render();else renderEditor();toast(`已添加 ${files.length} 张图片`)}catch(err){console.error(err);toast('保存图片失败。可能是当前浏览器存储空间不足，请导出备份并清理设备空间。',true)}finally{input.disabled=false}}
function closeLightbox(){document.getElementById('lightboxRoot').innerHTML='';document.body.style.overflow=state.editor?'hidden':''}
async function viewMedia(id,caption='图片'){const entry=await getItem('media',id);if(!entry){toast('找不到原图，可能需要重新导入备份',true);return}const full=await mediaURL(id,'full');document.getElementById('lightboxRoot').innerHTML=`<div class="lightbox" role="dialog" aria-modal="true" aria-label="${E(caption)}"><div class="lightbox-top">${button(`${icon('download',16)}${E(tr('原图下载'))}`,'download-media',`data-media="${E(id)}"`)}${button(icon('close',18),'close-lightbox','aria-label="关闭"','btn-icon')}</div><img src="${E(full)}" alt="${E(caption)}"/><div class="lightbox-caption">${E(caption)}<br/><span class="tiny" style="opacity:.7">${E(entry.name||'原图')} · ${(entry.size/1024/1024).toFixed(2)} MB</span></div></div>`;document.body.style.overflow='hidden'}
async function downloadMedia(id){const entry=await getItem('media',id);if(!entry){toast('图片不存在',true);return}downloadBlob(entry.blob,entry.name||`${id}.png`)}
function downloadBlob(blob,name){let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),45000)}
function encodeUTF8(str){return new TextEncoder().encode(str)}
const zipCrcTable=(()=>{let tab=[];for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);tab[i]=c>>>0}return tab})();
function crc32(bytes){let crc=0xffffffff;for(const v of bytes)crc=zipCrcTable[(crc^v)&255]^(crc>>>8);return (crc^0xffffffff)>>>0}
function u16(v,a,i){a.setUint16(i,v,true)}function u32(v,a,i){a.setUint32(i,v,true)}
function zipDate(d=new Date()){const y=Math.max(1980,d.getFullYear());return {date:((y-1980)<<9)|((d.getMonth()+1)<<5)|d.getDate(),time:(d.getHours()<<11)|(d.getMinutes()<<5)|((d.getSeconds()/2)|0)}}
async function buildZip(entries){const chunks=[],centers=[],stamp=zipDate();let offset=0;for(const entry of entries){const name=encodeUTF8(entry.name),blob=entry.blob instanceof Blob?entry.blob:new Blob([entry.blob]);if(blob.size>0xffffffff)throw Error('单个文件超过 ZIP 格式大小限制');const crc=crc32(new Uint8Array(await blob.arrayBuffer()));const loc=new ArrayBuffer(30);const v=new DataView(loc);u32(0x04034b50,v,0);u16(20,v,4);u16(0x0800,v,6);u16(0,v,8);u16(stamp.time,v,10);u16(stamp.date,v,12);u32(crc,v,14);u32(blob.size,v,18);u32(blob.size,v,22);u16(name.length,v,26);u16(0,v,28);chunks.push(loc,name,blob);centers.push({name,crc,size:blob.size,offset});offset+=30+name.length+blob.size;if(offset>0xffffffff)throw Error('备份过大，暂不支持超过 4GB 的 ZIP')}const centralOffset=offset;for(const e of centers){const c=new ArrayBuffer(46),v=new DataView(c);u32(0x02014b50,v,0);u16(20,v,4);u16(20,v,6);u16(0x0800,v,8);u16(0,v,10);u16(stamp.time,v,12);u16(stamp.date,v,14);u32(e.crc,v,16);u32(e.size,v,20);u32(e.size,v,24);u16(e.name.length,v,28);u16(0,v,30);u16(0,v,32);u16(0,v,34);u16(0,v,36);u32(0,v,38);u32(e.offset,v,42);chunks.push(c,e.name);offset+=46+e.name.length}const end=new ArrayBuffer(22),v=new DataView(end);u32(0x06054b50,v,0);u16(0,v,4);u16(0,v,6);u16(centers.length,v,8);u16(centers.length,v,10);u32(offset-centralOffset,v,12);u32(centralOffset,v,16);u16(0,v,20);chunks.push(end);return new Blob(chunks,{type:'application/zip'})}
function allMediaIds(){const ids=new Set();function find(o){if(!o||typeof o!=='object')return;if(Array.isArray(o)){o.forEach(find);return}for(const [key,val] of Object.entries(o)){if((key==='mediaId'||key==='coverId'||key==='avatarId')&&typeof val==='string'&&val)ids.add(val);else if(key!=='blob')find(val)}}find(settings);TYPES.forEach(type=>records[type].forEach(find));return [...ids]}
async function exportBackup(){if(state.busy)return;state.busy=true;toast('正在打包资料与高清原图…');try{const entries=await getAll('entries');const manifest={app:'maki-workbench',version:APP_VERSION,exportedAt:now(),entries,media:[]};const zipFiles=[];for(const id of allMediaIds()){const m=await getItem('media',id);if(!m)continue;const ext=/image\/png/i.test(m.mime)?'.png':/image\/webp/i.test(m.mime)?'.webp':/image\/gif/i.test(m.mime)?'.gif':/image\/jpeg/i.test(m.mime)?'.jpg':/image\/avif/i.test(m.mime)?'.avif':'.img';const path='assets/'+id+ext;manifest.media.push({id,path,name:m.name,mime:m.mime,size:m.size});zipFiles.push({name:path,blob:m.blob})}zipFiles.unshift({name:'manifest.json',blob:new Blob([JSON.stringify(manifest,null,2)],{type:'application/json'})});const zip=await buildZip(zipFiles);const date=new Date().toISOString().slice(0,10);downloadBlob(zip,`maki-workbench-backup-${date}.zip`);toast(`备份已生成：${records.ocs.length+records.paro.length+records.commissions.length+records.ideas.length} 条记录、${manifest.media.length} 张原图`)}catch(err){console.error(err);toast('备份失败：'+(err?.message||'未知错误'),true)}finally{state.busy=false}}
async function readZipFile(file){const tailSize=Math.min(file.size,65557),tail=new DataView(await file.slice(file.size-tailSize).arrayBuffer());let pos=-1;for(let i=tail.byteLength-22;i>=0;i--){if(tail.getUint32(i,true)===0x06054b50){pos=i;break}}if(pos<0)throw Error('不是有效的 ZIP 文件');const total=tail.getUint16(pos+10,true),centralBytes=tail.getUint32(pos+12,true),centralOffset=tail.getUint32(pos+16,true);if(total>5000||centralBytes>10*1024*1024)throw Error('备份内容数量异常');if(centralOffset+centralBytes>file.size)throw Error('ZIP 索引损坏');const center=new DataView(await file.slice(centralOffset,centralOffset+centralBytes).arrayBuffer());let o=0,items=new Map();for(let i=0;i<total;i++){if(o+46>center.byteLength||center.getUint32(o,true)!==0x02014b50)throw Error('ZIP 文件索引损坏');const method=center.getUint16(o+10,true),compressed=center.getUint32(o+20,true),size=center.getUint32(o+24,true),nameLen=center.getUint16(o+28,true),extra=center.getUint16(o+30,true),comment=center.getUint16(o+32,true),offset=center.getUint32(o+42,true);if(o+46+nameLen+extra+comment>center.byteLength)throw Error('ZIP 文件名损坏');const name=new TextDecoder().decode(new Uint8Array(center.buffer,center.byteOffset+o+46,nameLen));if(method!==0)throw Error('只支持由本工作台导出的原始 ZIP 备份');const head=new DataView(await file.slice(offset,offset+30).arrayBuffer());if(head.byteLength<30||head.getUint32(0,true)!==0x04034b50)throw Error('ZIP 内容损坏');const start=offset+30+head.getUint16(26,true)+head.getUint16(28,true);if(start+compressed>file.size||size!==compressed)throw Error('ZIP 文件大小错误');items.set(name,file.slice(start,start+compressed));o+=46+nameLen+extra+comment}return items}
function validateBackup(m){if(!m||m.app!=='maki-workbench'||m.version!==APP_VERSION||!Array.isArray(m.entries)||!Array.isArray(m.media))throw Error('备份格式与当前版本不兼容');if(m.entries.length>30000||m.media.length>5000)throw Error('备份记录数量异常');const keys=new Set();for(const item of m.entries){if(!item||typeof item.key!=='string'||keys.has(item.key)||!['settings',...TYPES].includes(item.type))throw Error('备份中的记录格式不正确');keys.add(item.key);if(item.type!=='settings'&&(!item.data||typeof item.data.id!=='string'||item.key!==item.type+':'+item.data.id))throw Error('备份中的记录 ID 不匹配')}for(const med of m.media){if(!med||typeof med.id!=='string'||!/^assets\/[\w-]+\.[a-z0-9]+$/i.test(med.path))throw Error('备份中有不安全的附件路径')}}
async function importBackup(file){if(state.busy)return;state.busy=true;toast('正在检查备份文件…');try{if(file.size>3.9*1024**3)throw Error('单个 ZIP 文件不能大于 4GB');const zip=await readZipFile(file);if(!zip.has('manifest.json'))throw Error('备份中找不到 manifest.json');const m=JSON.parse(await zip.get('manifest.json').text());validateBackup(m);for(const entry of m.media){if(!zip.has(entry.path))throw Error('缺少图片附件：'+entry.path)}if(!confirm(`即将从备份恢复：\n${m.entries.filter(x=>x.type!=='settings').length} 条记录、${m.media.length} 张图片。\n\n这会【覆盖当前设备上的全部工作台资料】。\n建议先导出现有备份。\n\n确定继续吗？`))return;await new Promise((resolve,reject)=>{const tx=db.transaction(['entries','media'],'readwrite');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);const entryStore=tx.objectStore('entries'),mediaStore=tx.objectStore('media');entryStore.clear();mediaStore.clear();for(const entry of m.entries)entryStore.put(entry);for(const med of m.media){const blob=zip.get(med.path).slice(0,undefined,med.mime||'application/octet-stream');mediaStore.put({id:med.id,name:med.name||med.id,mime:med.mime||'application/octet-stream',size:blob.size,blob,thumb:null,createdAt:now()})}});for(const u of imageCache.values())URL.revokeObjectURL(u);imageCache.clear();await refreshRecords();state.section='home';state.detailId=null;render();toast(`导入完成！恢复了 ${m.media.length} 张图片`)}catch(err){console.error(err);toast('导入失败：'+(err?.message||'未知错误'),true)}finally{state.busy=false;document.getElementById('importFile').value=''}}
async function handleAction(action,el,event){switch(action){
case 'overlay-close':if(event.target===el)closeEditor();break;
case 'new-oc':startEditor('ocs');break;
case 'new-paro':startEditor('paro');break;
case 'new-commission':startEditor('commissions');break;
case 'new-idea':startEditor('ideas');break;
case 'detail':state.section=el.dataset.type;state.detailId=el.dataset.id;window.scrollTo(0,0);render();break;
case 'back-list':state.detailId=null;render();break;
case 'edit-record':startEditor(el.dataset.type,el.dataset.id);break;
case 'delete-record':await removeRecord(el.dataset.type,el.dataset.id);break;
case 'copy-record':{const r=findRecord(el.dataset.type,el.dataset.id);if(r)await copyText(recordText(el.dataset.type,r));break}
case 'close-editor':closeEditor();break;
case 'save-editor':await saveEditor();break;
case 'array-add':collectEditor();state.editor[el.dataset.kind]??=[];state.editor[el.dataset.kind].push(el.dataset.kind==='aus'?{name:'',description:''}:{key:'',value:''});renderEditor();break;
case 'array-remove':collectEditor();state.editor[el.dataset.kind]?.splice(+el.dataset.index,1);renderEditor();break;
case 'remove-cover':collectEditor();state.editor.coverId=null;renderEditor();break;
case 'remove-media':collectEditor();state.editor[el.dataset.kind]?.splice(+el.dataset.index,1);renderEditor();break;
case 'reorder-media':{collectEditor();const list=state.editor[el.dataset.kind],from=+el.dataset.index,to=from+ +el.dataset.direction;if(!list||to<0||to>=list.length)break;[list[from],list[to]]=[list[to],list[from]];renderEditor();break}
case 'restore-version':await restoreVersion(el.dataset.id,+el.dataset.index);break;
case 'set-view':state.display=el.dataset.view;render();break;
case 'set-accent':settings.accent=el.dataset.color;await saveSettings();render();break;
case 'quote-lang':state.quoteLang=el.dataset.lang==='ja'?'ja':'zh';animateQuote();if(quoteInterval!==null){clearInterval(quoteInterval);quoteInterval=null}startQuoteRotation();break;
case 'quote-next':advanceQuote(false,1);break;
case 'quote-prev':advanceQuote(false,-1);break;
case 'quote-pause':state.quotePaused=!state.quotePaused;const playEl=document.getElementById('quotePauseButton');if(playEl){playEl.textContent=state.quotePaused?'▶':'Ⅱ';playEl.setAttribute('aria-label',state.quotePaused?'播放轮播':'暂停轮播');playEl.title=state.quotePaused?'播放轮播':'暂停轮播'}if(quoteInterval!==null){clearInterval(quoteInterval);quoteInterval=null}startQuoteRotation();break;
case 'quote-edit':setNav('settings');document.getElementById('higekiriQuoteSettings')?.scrollIntoView({block:'center',behavior:'smooth'});break;
case 'quote-add':settings.higekiriQuotes=[...settings.higekiriQuotes,{zh:'',ja:''}];await saveSettings();render();document.getElementById('higekiriQuoteSettings')?.scrollIntoView({block:'start'});break;
case 'quote-remove':if(settings.higekiriQuotes.length<=1)break;settings.higekiriQuotes=settings.higekiriQuotes.filter((_,i)=>i!==+el.dataset.index);await saveSettings();render();document.getElementById('higekiriQuoteSettings')?.scrollIntoView({block:'start'});break;
case 'view-media':await viewMedia(el.dataset.media,el.dataset.caption);break;
case 'download-media':await downloadMedia(el.dataset.media);break;
case 'close-lightbox':closeLightbox();break;
case 'export-backup':await exportBackup();break;
case 'import-backup':document.getElementById('importFile').click();break;
case 'open-search':state.section='ocs';state.detailId=null;state.query='';render();document.getElementById('collectionSearch')?.focus();break;
}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-nav],[data-action],[data-richcmd]');if(!el)return;if(el.hasAttribute('data-richcmd')){e.preventDefault();const cmd=el.dataset.richcmd;const editor=document.getElementById('richBackground');if(!editor)return;editor.focus();document.execCommand(cmd,false,el.dataset.value||undefined);return}if(el.hasAttribute('data-nav')){setNav(el.dataset.nav);return}if(el.hasAttribute('data-action')){try{await handleAction(el.dataset.action,el,e)}catch(err){console.error(err);toast('操作未完成：'+(err?.message||'未知错误'),true)}}});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-richcmd]'))e.preventDefault()});
document.addEventListener('input',e=>{if(e.target.id==='collectionSearch'){const pos=e.target.selectionStart||0;state.query=e.target.value;render();const next=document.getElementById('collectionSearch');next?.focus();try{next?.setSelectionRange(pos,pos)}catch{}}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.upload){await addUploadedFiles(el);return}if(el.dataset.quoteInput!==undefined){const idx=Number(el.dataset.quoteIndex),lang=el.dataset.quoteLang;if(Number.isInteger(idx)&&['zh','ja'].includes(lang)&&settings.higekiriQuotes?.[idx]){settings.higekiriQuotes[idx][lang]=el.value;await saveSettings()}return}
if(el.id==='quoteAutoplay'){settings.quoteAutoplay=el.checked;await saveSettings();return}
if(el.id==='collectionSort'){state.sort=el.value;render();return}if(el.id==='settingsLang'){settings.language=el.value;await saveSettings();render();return}if(el.id==='settingsTheme'){settings.theme=el.value;await saveSettings();render();return}if(el.id==='settingsFont'){settings.font=el.value;await saveSettings();render();return}if(el.id==='customAccent'){settings.accent=el.value;await saveSettings();render();return}if(el.id==='siteTitle'){settings.title=el.value.trim()||DEFAULT_SETTINGS.title;await saveSettings();render();toast('名称已更新');return}}catch(err){console.error(err);toast('设置保存失败',true)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.getElementById('lightboxRoot').children.length){closeLightbox();return}if(state.editor){closeEditor();return}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.section='ocs';state.detailId=null;state.query='';render();document.getElementById('collectionSearch')?.focus()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&state.editor){e.preventDefault();saveEditor().catch(console.error)}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-nav][role="button"]')){e.preventDefault();setNav(e.target.dataset.nav)}});
document.getElementById('importFile').addEventListener('change',e=>{if(e.target.files?.[0])importBackup(e.target.files[0]).catch(console.error)});
async function init(){try{if(!('indexedDB' in window))throw Error('该浏览器不支持 IndexedDB。请使用最新版 Chrome、Edge、Safari 或 Firefox。');db=await openDatabase();await refreshRecords();render();if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);if(navigator.storage?.persisted){const persistent=await navigator.storage.persisted();if(!persistent)console.info('建议定期导出备份，浏览器可能清理非持久化存储。')} }catch(err){console.error(err);document.getElementById('main').innerHTML=`<div class="empty-state"><div class="empty-medallion">!</div><h2>无法打开本地资料库</h2><p>${E(err?.message||'当前环境无法访问浏览器本地存储。')}</p><p>请使用普通浏览器窗口，通过 HTTPS 网站或本地服务器访问，不要使用无痕模式。</p></div>`}}
init();
